def verify():
    assert 1e8 * 0.05 / 8 / 1000 == 625 and 11 * 2 == 22 and 1000 + 500 == 1500
    assert abs(65536 * 8 / 0.1 / 1e6 - 5.24) < 0.01 and 2 ** 4 == 16 and 2 ** 12 - 2 == 4094
    assert (77 // 64) * 64 == 64 and 2 + 1 + 3 == 6 and 2 ** 12 == 4096
    assert abs(12000 / 1e8 * 1e6 - 120) < 1e-9 and (20 + 22 + 24 + 26) / 4 == 23 and 8e8 / 10 / 1e6 == 80


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
